// Signs the GET request to Convex. Same scheme as every LendLoop call:
// signature = HMAC-SHA256(secret, timestamp + "." + body), and a GET has no body.
const crypto = require('crypto');

const secret = $env.LENDLOOP_WEBHOOK_SECRET;
const baseUrl = $env.LENDLOOP_CONVEX_SITE_URL;
if (!secret || !baseUrl) {
  throw new Error('LENDLOOP_WEBHOOK_SECRET and LENDLOOP_CONVEX_SITE_URL must be set on this n8n instance');
}

const timestamp = String(Date.now());
const signature = crypto.createHmac('sha256', secret).update(`${timestamp}.`).digest('hex');

return [{ json: { url: `${baseUrl}/overdue-loans`, timestamp, signature } }];

// One item per overdue loan that has not been reminded today.
// The idempotency key allows one reminder per loan and per day: running this
// workflow again, or retrying a failed call, can never create a second one.
const today = new Date().toISOString().slice(0, 10);
const loans = $input.first().json.loans ?? [];

return loans
  .filter((loan) => !loan.reminderSentToday)
  .map((loan) => ({
    json: {
      loanId: loan.loanId,
      borrowerEmail: loan.borrowerEmail,
      toolName: loan.toolName,
      endDate: loan.endDate,
      idempotencyKey: `${loan.loanId}:${today}`,
    },
  }));

// Mock reminder: builds the message that would be emailed to the borrower.
// Swap this node for an email node to send it for real.
return $input.all().map((item) => ({
  json: {
    ...item.json,
    to: item.json.borrowerEmail,
    subject: `Reminder: please return the ${item.json.toolName}`,
    text: `The ${item.json.toolName} was due back on ${item.json.endDate}.`,
    status: 'sent',
  },
}));

// Signs the write-back to Convex. The body is built once, as text, and that
// exact text is both signed and sent. It carries three fields and no email.
const crypto = require('crypto');

const secret = $env.LENDLOOP_WEBHOOK_SECRET;
const baseUrl = $env.LENDLOOP_CONVEX_SITE_URL;

return $input.all().map((item) => {
  const { loanId, idempotencyKey, status } = item.json;
  const body = JSON.stringify({ loanId, idempotencyKey, status });
  const timestamp = String(Date.now());
  const signature = crypto.createHmac('sha256', secret).update(`${timestamp}.${body}`).digest('hex');
  return { json: { url: `${baseUrl}/reminder-status`, body, timestamp, signature } };
});
